return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'so_SO','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T12:05:05+00:00','po-revision-date'=>'2026-09-26T12:05:05+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Soo-saaridii aasaaska ahayd ee Page Builder Sandwich oo la dib u dhisay: shaashadda dejinta iyo Ku saabsan, lakabka wax soo saarka hore ee Footprint-Free ah, iyo hal baloog oo tusaale ah.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Bixiyeyaasha AI','The makers of ChatGPT. A good all-rounder.'=>'Soo-saarayaasha ChatGPT. Qalab wareegsan oo wanaagsan.','The makers of Claude. Strong at writing and careful reasoning.'=>'Sameeyeyaasha Claude. Ku xooggan qorista iyo sababaynta taxaddarka leh.','Google\'s Gemini models. Fast and inexpensive.'=>'Modellada Gemini ee Google. Degdeg ah oo jaban.','A European AI company with fast, inexpensive models.'=>'Shirkad AI oo laga leeyahay Yurub oo leh moodallo dhaqso badan oo jaban.','Low-cost models that are good at writing and code.'=>'Moodeelada jaban ee ku fiican qorista iyo koodhka.','One key for models from many different providers.'=>'Hal furaha oo loogu talagalay moodooyinka ka kala yimid bixiyeyaal badan.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Adeeg kasta oo u shaqeeya sida OpenAI\'s API, oo ay ku jirto qaab ay ku shaqeyneyso kombiyuutarkaaga ama adeegahaaga.','General (used when nothing more specific is set)'=>'Guud ahaan (la isticmaalo marka wax kale oo gaar ah aan la cayimin)','Writing and rewriting'=>'Qoraalka iyo dib-u-qorista','Translation'=>'Turjumaad','Code and CSS'=>'Code iyo CSS','Sorry, you are not allowed to access this page.'=>'Waan ka xumahay, looguma oggola inaad gasho boggan.','These settings are shared by every plugin that uses them: %s.'=>'Goobahaan waxaa wada wadaagaya dhammaan qalabka isticmaala: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Furayaashaadu waxay ku dhex jiraan xog-ururinta degelkan, waxaana loo diraa oo keliya bixiyaha aad dooratay — waligoodna nooma soo diraan.','Step 1 of 2: choose an AI provider'=>'Tallaabada 1 ee 2: dooro bixiye AI ah','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Waxaad keenaysaa furahaaga gaarka ah, markaa waxaad bixiyaha si toos ah uga bixinaysaa wixii aad isticmaasho. Ma hubtid? Mid kasta oo ka mid ah kuwan ayaa si fiican u shaqeeya; waxaad ku dari kartaa kuwo kale mark dambe.','Next'=>'Xiga','Step 2 of 2: connect %s'=>'Tallaabada 2 ee 2: ku xidh %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Geli cinwaanka adeeggaaga OpenAI-waafaqsan, oo ku dhammaanaya /v1. Muhiimad lama saaro furaha ilaa adeeggu uu mid codsado mooyaane.','Open %s and sign in (or create a free account).'=>'Fur %s oo lagalay (ama samee akoon bilaash ah).','the %s API keys page'=>'bogga %s fayaalal API','Create a new key and copy it.'=>'Abuur furaha cusub oo koobi garee.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Hoos ku dheji oo riix "Keydi oo tijaabi". Waxaan direynaa hal codsi yar si loo hubiyo inay shaqeyneyso.','Most providers need a little credit on the account before a key works: %s.'=>'Int aksaar ah waxay u baahan yihiin xoogaa deyn ah oo ku jirta akoonka ka hor int>**C**aash**a** furaha uu shaqeeyo: %s.','add credit'=>'ku dar deyn','← Choose a different provider'=>'← Dooro bixiye kale','Address'=>'Ciwaan','Saved key ends in …%s — paste a new one to replace it'=>'Furaha la key oo la keydiyay wuxuu ku dhamaadaa …%s — geli mid cusub si aad ugu beddesho','Key (optional)'=>'Furaha (ikhtiyaari)','API key'=>'Furaha API','Save and test'=>'Kaydi oo tijaabi','Providers'=>'Bixiyeyaasha','Provider'=>'Bixiyaha','Status'=>'Xaaladda','Key'=>'Furaha','Get a key'=>'Hel fure','Test'=>'Tijaabi','Remove'=>'Ka saar','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Noocyada cusub ee qalab-kordhinta ayaa keydiyay: cusboonaysii qalab-kordhintakan, ama geli furaha mar kale.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Furaha la keydiyay lama furan karo mar dambe (furayaasha amniga ee boggu waa is beddeleen). Geli markale.','Not connected'=>'Lama xiriirin','Connected — last test passed %s'=>'Ku xidhan — imtixaankii ugu dambeeyay wuxuu guulaystay %s','Last test failed: %s'=>'Imtixaanesii ugu dambeeyay wuu guuldarraystay: %s','Connected — not tested yet'=>'Ku xidhan — wali lama tijaabin','Which model to use'=>'Waa maxay moodeelka la isticmaalayo','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ waxay calaamadinaysaa taladeena hawshaas. Liiska waxaa ku jira dhammaan noocyada uu furahaagu isticmaali karo, kuwaas oo si toos ah looga soo aqriyay bixiyaha.','— Recommended for the provider —'=>'— Waxaa lagula talinayaa bixiyaha —','Save models'=>'Kaydi moodoosyada','Refresh the model lists from the providers'=>'Ka cusboonaysii liiska noocyada alaab-qeybiyeyaasha','best quality'=>'tayada ugu fiican','lowest cost'=>'kharashka ugu hooseeya','fastest'=>'ugu dhaqso badan','Add a model yourself'=>'Naftaada ku dar qaabka','A model came out today? Paste its exact name to use it straight away.'=>'Moodeel ayaa soo baxay maanta? Geli magaciisa saxda ah si aad isla markiiba u isticmaasho.','Model name'=>'Magaca moodeelka','Add model'=>'Ku dar nooc','Recommended models list'=>'Liiska moodellada lagu talinayo','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Liiska moodellada lagu taliyay lama xaqiijin karo, markaa lama tusi taliyo. Dib u rakib furaha (plugin-ka), ama shid cusboonaysiinta maalinlaha ah ee hoose.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Liiska la isticmaalayo waxaa la daabacay %s. Cusboonaysiin kasta oo plugin ah waxay keentaa mid cusub.','Also check Zinn Digital® once a day for an updated list.'=>'Sidoo kale hubi Zinn Digital® hal mar maalintii si aad u hesho liis cusboonaysiiyey.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Kaliya codsi dejisan oo fudud ayaa la dirayaa: ma jiro furaha, ma jiro ciwaanka bogga, waxba kama jiraan waxa ku saabsan waxa aad ku leedahay. Liiska waa la saxiixay, liiskuna wuu fashilmayaa haddii hubinta saxiixu ay guuldarraysato waa la is indhatirayaa.','Last checked %1$s: %2$s.'=>'Markii ugu dambeysay ee la hubiyay %1$s: %2$s.','Save, and check now if turned on'=>'Keydi, oo hadda hubi haddii la shiday','a newer list was installed'=>'liis ka cusub ayaa la rakibay','already up to date'=>'hore ula socota wakhtiga','the download failed the signature check and was ignored'=>'soo dejintu waxay ku guuldareysatay hubinta saxiixa waana la iska indhatiray','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® lama gaari karin; liiska hadda jira waa in la isticmaalo','turned off'=>'demiska','Open'=>'Fur','Check their status page'=>'Ka eeg boggooda xaaladda','Open your billing page'=>'Fur boggaaga biilasha','Open your API keys page'=>'Fur bogtaada furayaasha API','Open the AI settings'=>'Fur habaynta AI','Sorry, you are not allowed to do that.'=>'Waan ka xumahay, looma oggola inaad taas sameyso.','Unknown provider.'=>'Bixiyaha la garan waayay.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Geli cinwaanka adeegaga, tusaale ahaan http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Taasi uma eka furaha API. Nuqul ka yeeg mar kale, adiga oo aan wadata bannaan.','Paste your API key first.'=>'Marka hore dheji furahaaga API.','Key removed.'=>'Furaha waa la saaray.','Models saved.'=>'Qaababka la kaydiyay.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Geli magaca saxda ah ee moodalka, tusaale ahaan sida dukumentiyada bixiyuhu u qoreen.','Added %s. Choose it under "Which model to use".'=>'La daray %s. Ka dooro hoosta "Nooca la isticmaalayo".','Model removed.'=>'Qaabka waa la saaray.','Daily updates are off. The list that came with the plugin is used.'=>'Cusboonaysiinada maalinlaha ah waa damisanyihiin. Waxaa la isticmaalaa liiska uu la yimid furaha.','Checked: %s.'=>'La hubiyay: %s.','Model lists refreshed.'=>'Liisaska noocyada waa la cusboonaysiiyay.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Furahaaga AI waxaa keydiyey nooc cusub oo ka mid ah fiilooyinkaaga (plugins). Cusboonaysii fiiladan, ama mar labaad geli furaha oo ku jira dejinta AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Furahaaga AI ee la keydiyay dib looma furan karo (furayaasha amniga ee boggu waa is beddeleen). Dib u geli dejinta AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI-du wali lama hagaajin. Ku dar furaha bixiyaha AI goobaha AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Shaqadan looma dooran nooc model ah. Mid ka dooro dejinta AI.','That AI provider is not supported by this version of the plugin.'=>'Bixiyaha AI-gaas laguma taageero noocaan ah ee qalabka dheeriga ah (plugin).','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Boggan ma gaari karo adeeggaaga AI. Hubi inuu shaqaynayo iyo in cinwaankiisa laga soo gaari karo server-kaaga shabakadda (adeeg ka jira kombuyuutarkaaga lagama soo gaari karo bog lagu martigeliyay).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Goobtankani ma gaari karo %s. Ka eeg boggooda xaaladda; haddii ay shaqeynayaan, waxaa laga yaabaa in martigeliyahaagu uu xirayo xiriirada baxaya, ama ciwaanka waa khalad.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s waxaan ay leeyihiin koontadaadu wax lacag ama kooto ah oo soo hartay ma leh. Ku dar lacag ama kor u qaad xadkaaga koontadaada iyaga, kadibna isku day mar kale.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s ma aysan aqbalin furahaaga. Waxaa laga yaabaa in si khaldan loo qoray, la baabi\'iyay ama uu dhacay. Abuur fure cusub oo halkaan ku dheji.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s wuu diiday codsigan furahaaga. Furaha waxaa laga yaabaa inuusan heli karin qaabkan ama muuqaalkan, ama akoonkaaga ayaa u baahan in la xaqiijiyo.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Qaabka "%1$s" kama heli kartid %2$s furehaada. Ka dooro qaab kale oo ka tirsan habaynta AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Qorshahaaga %2$s kuma jiro tusaalaha "%1$s". Dooro tusaale kale oo ku jira dejinta AI, ama ku cusboonaysii qorshahaaga iyaga.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s waxay xaddidaysaa inta uu furahaagu si degdeg ah u diri karo codsiyada. Sug hal daqiiqo oo dib u day, ama kor u qaad xadka heerkaaga iyaga la leh.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s wax dhibaato ah ayaa haysata hadda (cillad ama culays dhinaceeda ah). Wax qalad ah kama jiraan dejintaada. Isku day mar kale dhawaan.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Codsiga AI wuu fashilmay sabab aanan garan karin. Isku day mar kale; haddii ay sii dhacdo, la xiriir taageerada oo u dir macluumaadka hoose.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Bixiyaha AI wuxuu ku jawaabay qaab uusan fiidiyowgani akhriyi karin. Isku day mar kale; haddii ay sii socoto, dooro qaab kale ama la xiriir taageerada.','Custom (OpenAI-compatible)'=>'Caadi ah (OpenAI-compatible)','Save a key for this provider first.'=>'Markabkan geli furaha bixiyahaan marka hore.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Farahaagu wuu shaqeynayaa, laakiin bixiyuhu ma liisgareynayo wax moodel qoraal ah. Ku dar moodel adiga laftaadu hoos.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'La xirray. %1$s waxa uu ku jawaabay adigoo isticmaalaya %2$s. Astaamahaaga AI waa diyaar in la isticmaalo.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Doorka isticmaalahaagu ma oggola inaad isticmaasho AI boggan. Weydiiso maamulaha.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Webkaan wuxuu gaaray xadka kharashkiisa bishii ee AI. Maamulaha ayaa ku kordhin kara habaynta AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Goobtan waxay gaartay xadka bisha ee codsiyada AI. Maamulaha ayaa kor u qaadi kara goobaha AI.','Usage and cost'=>'Isticmaalka iyo kharashka','The log, limits and role permissions apply to AI used through: %s.'=>'Diiwaanka, xadka iyo ogolaanshaha doorka waxaa lagu dabaqaa sirdoonka macmalka (AI) ee lagu isticmaalo: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Qiimayaashu waa kuwo qiyaas ah, oo laga soo saaray qiimayaasha la daabacay; qaab aan la aqoon qiimihiisu wuxuu u tirsan yahay eber.','This month: %1$s requests, about %2$s.'=>'Bishan: %1$s codsiyo, ku dhawaad %2$s.','When'=>'Goorta','Who'=>'Yaa','Used for'=>'Loogu isticmaalay','Model'=>'Qaabka','Tokens in / out'=>'Calaamadaha gudaha / dibadda','About'=>'Ku saabsan','Result'=>'Natiijo','No AI requests have been made yet.'=>'Weli lama samayn codsiyo AI ah.','Done'=>'La dhammeeyey','Limits and permissions'=>'Xadka iyo fasaxyada','Monthly spending limit (US dollars)'=>'Xadka kharashka bisha (US dollars)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Ka tag eber haddii aadan xad la rabin. AI-du way istaagaysaa inta ka dhiman bisha marka qiimaha lagu qiyaaso uu gaaro xadkaas.','Monthly request limit'=>'Xadka codsiga bishii','Leave empty for no limit.'=>'Si aad u noqotid mid aan xaddidnayn, banaan uga tag.','Who may use AI'=>'Qofka isticmaali kara AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Castaallo ha dooran si aad u oggolaato qof kasta oo isticmaali kara sifooyinka furaha (plugin) inuu isticmaalo AI. Maamulayaashu mar walba way isticmaali karaan.','Save limits and permissions'=>'Kaydinta xadka iyo ogolaanshaha','Limits and permissions saved.'=>'Xadka iyo fasaxyada waa la keydiyay.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Qoraallada shaashadda maamulaha ayaa ka maqan nuqulkan barnaamijka dheeriga ah (plugin). Dib uga rakib xirmo la sii daayay.','This screen needs JavaScript.'=>'Shaarkani wuxuu u baahan yahay JavaScript.','Languages'=>'Luuqadaha','Upgrade'=>'Cusbooneysii','Pricing'=>'Qiimaha','Start Trial'=>'Bilow Imtixaanka','Account'=>'Koontada','Contact Us'=>'Nala Xiriir','Affiliation'=>'Xiriirinta','the kind of softwarePlugin'=>'Kudaraha','greetingHey %s,'=>'Hey %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Ku biir si aad u hesho ogeysiisyo iimayl oo ku saabsan cusboonaysiinta amniga iyo astaamaha, waxyaabo waxbarasho, iyo dalabyo mararka qaar, oo aad la wadaagto macluumaad guud oo ku saabsan deegaanka WordPress. Tani waxay naga caawinaysaa inaan %s ka dhigno mid si fiican ula jaanqaada bogaaga oo si wanaagsan u qabta waxa aad u baahan tahay.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Ku biir si aad u hesho ogeysiisyo iimayl oo ku saabsan cusboonaysiinta amniga iyo astaamaha, waxyaabo waxbarasho, iyo dalabyo mararka qaar, oo aad la wadaagto macluumaad guud oo ku saabsan deegaanka WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Haddii aad ka boodho arrintan, waa caadi! %1$s weli si fiican ayuu u shaqayn doonaa.','Allow & Continue'=>'Oggolow & Sii wad','verbSkip'=>'Ka bood','Skipping, please wait'=>'Waa la gudbayaa, fadlan sug','Continue'=>'Sii wad','Please wait'=>'Fadlan sug','as activating pluginActivating'=>'Waa la howlgeliyaa','This will allow %s to'=>'Tani waxay u oggolaan doontaa %s inuu','Privacy Policy'=>'Politikada Qarsoodiga','Terms of Service'=>'Shuruudaha Adeegga','License Agreement'=>'Heshiiska Shatiga','Have a license key?'=>'Ma haysataa furaha shatiga?','Activate License'=>'Dhaqaaji Shatiga','View Basic Profile Info'=>'Eeg Macluumaadka Kooban ee Profile-ka','Your WordPress user\'s: first & last name, and email address'=>'Isticmaalahaaga WordPress: magaca koowaad &ka dambe, iyo ciwaanka iimaylka','View Basic Website Info'=>'Arag macluumaadka guud ee mareegta','Homepage URL & title, WP & PHP versions, and site language'=>'URL-ka bogga hoose & cinwaanka, noocyada WP & PHP, iyo luqadda bogga','View Basic %s Info'=>'Arag macluumaadka guud ee %s','Current %s & SDK versions, and if active or uninstalled'=>'SDK-yada %s ee hadda & noocyada, iyo haddii ay shaqeynayaan ama la uninstall-gareeyay','Newsletter'=>'Wargeyska xilliyeedka','Updates, announcements, marketing, no spam'=>'Cusbooneysiin, ogeysiis, suuq-geyn, spam ma jiro','View Diagnostic Info'=>'Eeg Xogta Cilmi-baarista','WordPress & PHP versions, site language & title'=>'Noocyada WordPress & PHP, luqadda iyo cinwaanka bogga','View Plugins & Themes List'=>'Eeg Liiska Hajtisyada & Mawduucyada','Names, slugs, versions, and if active or not'=>'Magacyada, gaabisyada, noocyada, iyo haddii ay shaqeynayaan iyo inkale','optional'=>'ikhtiyaari ah','Never miss an important update'=>'Abid walba oo muhiim ah ha seegin','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Waxaan soo bandhignay ikhtiyaarkan si aadan weligood u seegin warbixin muhiim ah oo aad nooga caawiso inaan ka dhigno %s mid si fiican ula jaanqaadaysa boggaaga oo si wanaagsan u qabaneysa waxaad uga baahan tahay.','Thank you for updating to %1$s v%2$s!'=>'Waad ku mahadsan tahay inaad u cusboonaysiisay %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Horgalku waa inay noqotaa 1 ilaa 8 xaraf oo yar ama nambaro ah, ku billowda xaraf, mana aha inay magac ka dhigto bulginka.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Waxaa dhisay Neil Lock, oo ah madaxa fulinta ee Zinn Digital® Ltd','Version %s'=>'Nooca %s','Page Builder Sandwich website'=>'Mareegta Page Builder Sandwich','Zinn Digital® website'=>'Mareegta Zinn Digital®','Settings saved.'=>'Dejinta waa la keydiyay.','See the Pro plans and pricing'=>'Eeg qorshayaasha Pro iyo qiimahooda','Front-end output'=>'Soosaarka hore','Class name prefix'=>'Horgalaha magaca fasalka','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Magac kasta oo fasalka ah ee uu turjumaaddu ku daabaco bogaggaaga wuxuu ka bilaabmayaa horgalahan, si uusan bogaggu u muujin kan dhisay. 1 ilaa 8 xaraf oo yar ama nambarro ah, oo ka bilaabmaya xaraf.','Save'=>'Keydi','Beta updates'=>'Cusbooneysiinaha Beta','This site receives beta versions as updates.'=>'Boggan wuxuu helayaa noocyada beta cusbooneysiin ahaan.','This site receives stable versions only.'=>'Boggan wuxuu helayaa noocyada xasiloon kaliya.','Change this on the Account page'=>'Tan kaga beddel bogga Koontada','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Noocyada Beta waxaa la siiyaa rakibaadaha Pro ee ruqseysan ee ku xiran akoonkooda. Marka la xiro, waxaad ka soo biiri kartaa bogga Akoonka.','Content'=>'Muxuu ku jiraa','Heading'=>'Madax','Text'=>'Qoraal','Style'=>'Habka','Plain'=>'Caadi','Accent'=>'Lamaanaha luqadda','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Ma jiraan luuqado la isku beddelayo. Beddeluhu wuxuu soo baxayaa marka qalabka turjumaaddu uu liis gareeyo laba ama in ka badan oo luuqadood.','Switcher'=>'Beddeleeyaha','Accessible label'=>'Summaddu la heli karo','Show the current language'=>'Muuji luqadda hadda taagan','block titleLanguage switcher (sample)'=>'Badalka luqadda (muunad)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Wuxuu soo bandhigayaa luqadaha mareegaha ee laga helayo qalabka turjumaadda, marka uu mid ka mid ahi shaqeeyo. Haddii kale waxba ma soo bandhigayo.','block keywordlanguage'=>'Luqad','block keywordswitcher'=>'kala beddelaha','block titleSample content'=>'Nuxurka tusaalaha','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Cinwaan iyo baaragaraaf, oo lagu soo bandhigay magacyo fasal oo caadi ah. Waa blogga tixraaca ee heshiiska tarjumaadda.','block keywordsample'=>'muunad','block keywordtext'=>'qoraal']];